import{_ as t,H as p,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const F=JSON.parse('{"title":"开篇词 | 这一次，我们来采访毕玄","description":"","frontmatter":{},"headers":[],"relativePath":"超级访谈：对话毕玄/开篇词｜这一次，我们来采访毕玄.md","filePath":"超级访谈：对话毕玄/开篇词｜这一次，我们来采访毕玄.md","lastUpdated":1795560749000}'),E={name:"超级访谈：对话毕玄/开篇词｜这一次，我们来采访毕玄.md"};function s(n,e,l,o,r,A){return p(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="开篇词-这一次-我们来采访毕玄" tabindex="-1">开篇词 | 这一次，我们来采访毕玄 <a class="header-anchor" href="#开篇词-这一次-我们来采访毕玄" aria-label="Permalink to &quot;开篇词 | 这一次，我们来采访毕玄&quot;">​</a></h1><p>你好，非常高兴能和你在《超级访谈：对话毕玄》专栏见面，我是编辑叶芊。</p><p>你是不是很好奇，为什么这次要和毕玄对谈？答案很简单，因为这个人有一份神奇到独一档的职业经历。</p><p>2002 年大学生物系毕业后，他成为了一名做政府项目的小程序员，在小厂辗转了五年。到这里，看起来还没有什么太独特的，就是一个普通的非科班程序员。</p><p>但就在小厂的第五年，他被称为国内 OSGi 第一人，07 年年底顺势加入淘宝后，就开启了自己仿佛转岗无上限的成长之旅，你也可以简称——“开挂”。</p><p>一进淘宝，他就负责 HSF 的设计和实现，在 14 年后的现在，HSF 每天还都承担着百亿次以上的服务调用，是淘宝乃至阿里非常重要的中间件框架，但后来他居然跳去做了 NoSQL 数据库 HBase 的改进和落地，在接下来的 2011 年，他仿佛预测到了容器的技术浪潮，又转岗去负责淘宝私有云 T4 的设计和落地，比 Docker 都要早两年。</p><p>但那之后他居然又从研发转到了运维，成为了一名运维工具研究员，顺带 2013 年做了广为外界所熟知的淘宝异地多活改造，之后丝滑过渡到了更大的集团级项目——云资源统一调度，同时还带着研发效能部门，做研发效能工具。19 年他开始带视频云的业务团队，结果因为疫情视频领域爆火，部门备受瞩目，但下一年他却从阿里离开了。</p><p>现在他创业快一年了，是一家做资源调度产品公司的 CEO，据说天使轮已经融完了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%85%E7%BA%A7%E8%AE%BF%E8%B0%88%EF%BC%9A%E5%AF%B9%E8%AF%9D%E6%AF%95%E7%8E%84/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%85%E7%BA%A7%E8%AE%BF%E8%B0%88%EF%BC%9A%E5%AF%B9%E8%AF%9D%E6%AF%95%E7%8E%84/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/1.png" alt=""></a></p><p>这么看毕玄的职业经历，你说这个人，转岗也就转岗吧，方向判断得这么准，就像能预测下一个技术风口一样，关键是怎么还能做一个成一个？简直就是“谋事在人，成事也在人”的真实写照。</p><p>现在你是不是对他的洞察力很佩服，是不是在想，如果能搞到他判断方向的技巧和成事经验，对你的帮助一定很大。</p><p>正是因为这一点，我们从今年 2 月份开始筹备这个专栏，采访问题写了十几版，但因为档期和疫情几度差点夭折。每个月，我一边立一定能去采访的 Flag，一边因为北京杭州两地的疫情心惊胆战，果不其然 Flag 倒了无数次。最终到 7 月份我们才挤出了三天，完成了一场共计 13个小时的长谈，聊了 100 多个问题，终于，不负你的期待，我们挖到了这份来自毕玄的独家秘籍。</p><p>于是，专栏最有代表性的“高手锦囊”模块也就此诞生，从个人成事、方向选择、团队带领、做事文化、架构修炼这 5 大方面，把他分析问题的思路和做事情的方法浓缩给你。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%85%E7%BA%A7%E8%AE%BF%E8%B0%88%EF%BC%9A%E5%AF%B9%E8%AF%9D%E6%AF%95%E7%8E%84/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%B6%85%E7%BA%A7%E8%AE%BF%E8%B0%88%EF%BC%9A%E5%AF%B9%E8%AF%9D%E6%AF%95%E7%8E%84/images/%25E5%25BC%2580%25E7%25AF%2587%25E8%25AF%258D/2.png" alt=""></a></p><p>当然想要把方法论化为己用，你还需要丰富的案例，这就是专栏前三章的作用了。</p><p>在“初出茅庐”“江湖风云”“创业维艰”中，你将感受到这位技术大佬独特的人格魅力，这种魅力不仅来源于他判断方向的战略眼光和驾驭复杂多变局势的能力，还有他背后的有趣故事所带来的新维度、新认知、新启发。</p><p>毕竟单看他的经历，我们可能觉得他是一个“平平无奇”的成功人士，基本没什么障碍，一路升级上去就成功了。但在看完一两讲他的神奇经历之后，你对他的印象一定会有一百八十度的大反转……</p><p>简单举几个例子吧：</p><ul><li><p>面试，没写简历，也没答对几道题，他却进了淘宝？</p></li><li><p>写第一个系统 HSF，刚转正就差点把淘宝搞挂了？</p></li><li><p>处理故障，充分锻炼了编程能力，他却说这对公司是个恶性循环？</p></li><li><p>做异地多活被广为人知，他却说做大项目，千万不要塑造一个神？</p></li><li><p>转到前景堪忧的运维团队，他表示团队价值问题自己也解决不了？</p></li><li><p>集团级项目统一调度做成了，他说可能是因为时机？</p></li><li><p>……</p></li></ul><p>基本上所有我们认为有点奇怪的现象，在采访的时候他都说“这很正常”，这句毕玄的口头禅也能算得上是这个专栏的小彩蛋了，如果你好奇，可以统计一下都出现在了哪里。</p><p>所以如果要一句话介绍这个专栏，这并不是一位成功人士的回忆史，反而是一场 20 年踩坑经历的深度复盘，讲的是：一个很有个性的普通人，如何在互联网浪潮中辗转腾挪，找寻自己的发力点。当然等你看完，如果有其他想法，欢迎留言交流。</p><p>另外，如果你对毕玄做的一些项目感兴趣，期待了解更多的技术细节和方案，也不妨看看文末的「拓展阅读」，希望对你有帮助！</p><p>好啦，现在万事俱备，我们一起来认识下这位大神吧！</p>',23)])])}const B=t(E,[["render",s]]);export{F as __pageData,B as default};
